import sys
data = sys.stdin.read().split()
if data:
    n = int(data[0])
    tokens = data[1:1+n]
    stk = []
    for t in tokens:
        if t in ['+', '-', '*', '/']:
            b = stk.pop(); a = stk.pop()
            if t == '+': stk.append(a + b)
            elif t == '-': stk.append(a - b)
            elif t == '*': stk.append(a * b)
            elif t == '/': stk.append(int(a / b))
        else: stk.append(int(t))
    print(stk[0])
